using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CreatureWithEffectCustomTag", menuName = "Data/Battle/Battle Actions/Tags/CreatureWithEffectCustomTag", order = 0)]
public class CreatureWithEffectCustomTag : Tag
{
	[SerializeField]
	private bool purify;

	protected string GetCreatureWithEffectDescription()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedCreatureWithEffect();
	}

	protected string GetPurifyCorruptName()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedPurifyOrCorruptionWord(purify);
	}
}
